modules.text:
import { spawnSync } from "node:child_process"

export const defaultPsExecutable = "/bin/ps"

export interface System {
  readonly ownGroup: () => string
}

export const posixSystemWith = (executable?: string): System => ({
  ownGroup: () => spawnSync(executable ?? defaultPsExecutable, ["-o", "pgid="]).stdout
})

export const posixSystem: System = posixSystemWith()

import { statSync } from "node:fs"

const kibibyte = 1024
export const maximumJudgedFileBytes = 256 * kibibyte

export function judgeFile(path: string): boolean {
  return statSync(path).size <= maximumJudgedFileBytes
}

import { readFileSync } from "node:fs"

export interface GateRunner {
  readonly run: (ids: ReadonlyArray<string>) => string
}

export const sessionText = (path: string): string => readFileSync(path, "utf8").slice(0, maximumSessionFileBytes)

export const unavailableGateRunner: GateRunner = {
  run: (ids) => sessionText(ids.join("/"))
}

export const maximumSessionFileBytes = 4 * 1024 * 1024
